#!/usr/bin/env node
// Generate skills/*/contract.md, docs/CATALOG.md, docs/ORIGINALITY_LEDGER.md and docs/VALIDATION_MATRIX.md
// from catalog/skills.mjs, evidence/results.json (tests/run_checks.py) and evidence/reviews.json (human/agent reviews).
//   node tools/gen-docs.mjs
// Generated files say so at the top; edit the sources, not the output.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { skills, UPSTREAM, GLYPH } from "../catalog/skills.mjs";

function originPhrase(s) {
  if (s.origin === "upstream") return `Foundation skill from [simcraft](${UPSTREAM.url}) at \`${UPSTREAM.commit.slice(0, 7)}\` (MIT, ${UPSTREAM.author}), modified by SumitCraft.`;
  if (s.origin === "glyph") return `Imported from [Glyph-Skill](${GLYPH.url}) at \`${GLYPH.commit.slice(0, 7)}\` (MIT, ${GLYPH.author}); the bundle is kept as published.`;
  if (s.origin === "vendor") {
    const c = s.source?.commit || "";
    const pin = /^[0-9a-f]{7,40}$/.test(c) ? `\`${c.slice(0, 7)}\`` : c;
    return `Third-party skill from [${s.source.repo}](${s.source.url}) (${s.source.license}, ${s.source.author}), ${pin}. SumitCraft set the folder name and the description so the skill fills one gap (${s.gap}). The method is upstream.`;
  }
  return "SumitCraft addition.";
}

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const read = (p, d) => { try { return JSON.parse(fs.readFileSync(path.join(ROOT, p), "utf8")); } catch { return d; } };
const results = read("evidence/results.json", { skills: {} }).skills;
const reviews = read("evidence/reviews.json", { reviews: {} }).reviews;
const statics = read("evidence/static/validate.json", null);
const GEN = "<!-- generated by tools/gen-docs.mjs from catalog/skills.mjs and evidence/; do not edit by hand -->";
const NEED = { node: "Node.js 18.19+", python: "Python 3.9+", git: "Git", ffmpeg: "ffmpeg (on PATH or FFMPEG)", playwright: "Playwright npm package (npm install)",
  chromium: "Playwright Chromium binary (npx playwright install chromium, ~150-200 MB)", numpy: "NumPy", matplotlib: "Matplotlib", pypdf: "pypdf", pyyaml: "PyYAML",
  opencv: "OpenCV (opencv-python-headless)", whisper: "faster-whisper or mlx-whisper in rough-cut/.venv (weights 0.5-1.5 GB on first use)", tesseract: "tesseract OCR",
  three: "three@0.170.0 in the work folder", "gemini-key": "GEMINI_API_KEY (user's own)", "openai-key": "OPENAI_API_KEY (user's own)",
  bun: "Bun 1.1+ (the long-form-storyboard checker; https://bun.sh)" };
const list = (a) => (a && a.length ? a.map((x) => `- ${x}`).join("\n") : "- none");
const statusOf = (n) => results[n]?.status || "not run";
const review = (n) => reviews[n] ? `${reviews[n].kind}: ${reviews[n].what}` : "none recorded";

function workflow(name) {
  const t = fs.readFileSync(path.join(ROOT, "skills", name, "SKILL.md"), "utf8");
  const pats = [/^## (?:\d+\.|Step \d+:?)\s*(.+)$/gm, /^### \d+\.\s*(.+)$/gm, /^\d+\. \*\*(.+?)\*\*/gm];
  for (const re of pats) { const m = [...t.matchAll(re)].map((x) => x[1].replace(/[*`]/g, "").replace(/\.$/, "")); if (m.length >= 2) return m; }
  return ["See SKILL.md (the method is written as prose sections)."];
}

// ---------- contracts ----------
for (const s of skills) {
  const r = results[s.name];
  const md = `${GEN}
# Contract: ${s.name}

${originPhrase(s)} Category: ${s.category}. Kind: ${s.kind === "guidance" ? "guidance-only (no scripts by design)" : "scripted"}.

## Purpose
${s.purpose}

## Use it for
${list(s.triggers.map((x) => `"${x}"`))}

## Not for
${list(s.nonTriggers)}

## Accepted inputs
${s.inputs}

## Deliverables
${s.deliverables}

## Prerequisites
Required:
${list(s.needs.required.map((x) => NEED[x] || x))}

Optional:
${list(s.needs.optional.map((x) => NEED[x] || x))}

Check them with \`node tools/doctor.mjs\` (Windows: \`tools\\doctor.ps1\`).

## Local and network behaviour
${s.network}

## Cost-sensitive operations
${s.cost}

## Workflow
${workflow(s.name).map((x, i) => `${i + 1}. ${x}`).join("\n")}

Full steps: [SKILL.md](SKILL.md).

## Human decisions
${list(s.decisions)}

## Quality checks
${list(s.checks)}

## Common failures
${list(s.failures)}

## Limitations
${list(s.limits)}

## Reproducible example
${s.example}

## Validation status
**${statusOf(s.name)}**${r ? ` (${r.when.slice(0, 10)}, ${r.platform})` : ""}. ${r ? r.observed : "No run recorded."}

Visual or audible review: ${review(s.name)}. Native Windows: not run. Details and gaps: [docs/VALIDATION_MATRIX.md](../../docs/VALIDATION_MATRIX.md).
`;
  fs.writeFileSync(path.join(ROOT, "skills", s.name, "contract.md"), md);
}

// ---------- catalog ----------
const cats = ["video", "engineering", "learning", "design", "planning", "docs"];
let cat = `${GEN}\n# Capability catalog\n\n${skills.length} skills: ${skills.filter((s) => s.origin === "upstream").length} foundation skills from simcraft (all kept under their upstream names), ${skills.filter((s) => s.origin === "sumitcraft").length} SumitCraft additions, Glyph (imported from the owner's Glyph-Skill repository), and ${skills.filter((s) => s.origin === "vendor").length} vendored third-party skills that fill gaps. Status is the strongest label a recorded run supports; see [VALIDATION_MATRIX.md](VALIDATION_MATRIX.md).\n`;
for (const c of cats) {
  cat += `\n## ${c[0].toUpperCase() + c.slice(1)}\n\n| Skill | Origin | What it does | Needs | Status |\n|---|---|---|---|---|\n`;
  for (const s of skills.filter((x) => x.category === c)) cat += `| [${s.name}](../skills/${s.name}/SKILL.md) | ${s.origin === "upstream" ? "foundation" : s.origin === "glyph" ? "**Glyph**" : s.origin === "vendor" ? "vendor" : "**addition**"} | ${s.purpose} | ${s.needs.required.join(", ") || "nothing"} | ${statusOf(s.name)} |\n`;
}
fs.writeFileSync(path.join(ROOT, "docs/CATALOG.md"), cat);

// ---------- originality ledger ----------
let led = `${GEN}\n# Originality ledger\n\nFor each capability: what is kept from upstream and why, what changed in the method, which new example shows the change, what evidence says it is better, and what remains inherited. Upstream: [simcraft](${UPSTREAM.url}) at \`${UPSTREAM.commit}\`. Every change is also visible as a diff from commit \`ba831ad\` (the unmodified import).\n\nReusing good upstream code is deliberate. Where a row says "paths only", SumitCraft's contribution to that skill is packaging, portability, a contract and a re-run, not a new method; it is not presented as original work.\n`;
for (const c of cats) {
  led += `\n## ${c[0].toUpperCase() + c.slice(1)}\n\n| Skill | Kept (why) | Changed in the method | New example | Evidence | Still inherited |\n|---|---|---|---|---|---|\n`;
  for (const s of skills.filter((x) => x.category === c)) led += `| ${s.name}${s.origin === "sumitcraft" ? " (new)" : s.origin === "glyph" ? " (Glyph)" : s.origin === "vendor" ? " (vendor)" : ""} | ${s.ledger.kept} | ${s.ledger.changed} | ${s.ledger.newExample} | ${statusOf(s.name)}: ${s.ledger.evidence} | ${s.ledger.inherited} |\n`;
}
fs.writeFileSync(path.join(ROOT, "docs/ORIGINALITY_LEDGER.md"), led);

// ---------- validation matrix ----------
const order = ["functionally verified", "smoke tested", "static checks passed", "blocked", "not run"];
const counts = Object.fromEntries(order.map((o) => [o, skills.filter((s) => statusOf(s.name) === o).length]));
let mx = `${GEN}
# Validation matrix

Labels, weakest to strongest: **not run**, **blocked**, **static checks passed**, **smoke tested** (ran end to end on a fixture, outputs inspected, no known answer), **functionally verified** (a known answer was checked: a planted failure caught and a fixed control passed, or output matched a reference tool). Visual or audible review is recorded separately and only when someone actually looked or listened. A mocked or dry-run provider call is never a provider pass.

**Platform of every recorded run: Linux (cloud container), headless Chromium with SwiftShader software WebGL.** Nothing has been run on native Windows or macOS. Windows support is implemented and documented, and its status is **unverified** until the commands in [SETUP.md](SETUP.md#verify-on-windows) are run on a Windows machine and recorded here.

Summary: ${order.map((o) => `${counts[o]} ${o}`).join(", ")} (of ${skills.length}).
${statics ? `\nStatic layer (\`node tools/validate.mjs\`, ${statics.when.slice(0, 10)}): ${statics.total - statics.failed}/${statics.total} checks pass (${Object.entries(statics.groups).map(([g, v]) => `${g} ${v.ok}/${v.total}`).join(", ")}).\n` : ""}
| Skill | Origin | Status | Visual / audible review | Fixture and observed result | Commands | Artifacts | Remaining gaps |
|---|---|---|---|---|---|---|---|
`;
for (const s of skills) {
  const r = results[s.name] || {};
  const esc = (x) => String(x || "").replace(/\|/g, "\\|").replace(/\n/g, " ");
  mx += `| ${s.name} | ${s.origin === "upstream" ? "foundation" : s.origin === "glyph" ? "Glyph" : s.origin === "vendor" ? "vendor" : "addition"} | **${statusOf(s.name)}** | ${esc(review(s.name))} | ${esc(r.observed || "not run")} | ${(r.commands || []).map((c) => "`" + esc(c).slice(0, 160) + "`").join("<br>")} | ${(r.artifacts || []).map((a) => esc(a)).join("<br>")} | ${esc(r.gaps)} Native Windows: not run. |\n`;
}
mx += `\nReproduce: \`python tests/run_checks.py\` (all) or \`python tests/run_checks.py <skill ...>\`, then \`node tools/gen-docs.mjs\`. Static: \`node tools/validate.mjs\`. Paths: \`node tests/unit_paths.mjs\`.\n`;
fs.writeFileSync(path.join(ROOT, "docs/VALIDATION_MATRIX.md"), mx);
console.log(`wrote ${skills.length} contracts, CATALOG.md, ORIGINALITY_LEDGER.md, VALIDATION_MATRIX.md (${order.map((o) => `${counts[o]} ${o}`).join(", ")})`);
